const COLORS = ["#e8590c","#d9480f","#c92a2a","#a61e4d","#862e9c","#5f3dc4","#364fc7","#1864ab","#0b7285","#087f5b","#2b8a3e","#5c940d","#e67700","#d6336c","#ae3ec9"];
const REGION_COLORS = {"Total North America":"#e8590c","Total S. & Cent. America":"#d9480f","Total Europe":"#364fc7","Total CIS":"#862e9c","Total Middle East":"#087f5b","Total Africa":"#e67700","Total Asia Pacific":"#1864ab","Total World":"#495057"};
const MARGIN_COLORS = {"USGC Medium Sour Coking":"#e8590c","NWE Light Sweet Cracking":"#364fc7","Singapore Medium Sour Hydrocracking":"#087f5b"};

const fmt = (v) => {
  if (v >= 1000) return (v/1000).toFixed(1) + "m";
  return v.toFixed(0);
};

const fmtK = (v) => typeof v === 'number' ? v.toLocaleString(undefined, {maximumFractionDigits:0}) : v;

const tabs = [
  {id:"balance",label:"Supply / Demand"},
  {id:"prices",label:"Crude Prices"},
  {id:"production",label:"Production"},
  {id:"consumption",label:"Consumption"},
  {id:"refining",label:"Refining"},
  {id:"margins",label:"Margins"},
];

const CustomTooltip = ({active, payload, label, suffix=""}) => {
  if (!active || !payload?.length) return null;
  return (
    <div style={{background:"rgba(15,15,20,0.95)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:6,padding:"10px 14px",fontSize:12,maxHeight:300,overflowY:"auto"}}>
      <div style={{color:"#868e96",marginBottom:6,fontWeight:600}}>{label}</div>
      {payload.map((p,i) => (
        <div key={i} style={{display:"flex",alignItems:"center",gap:8,marginBottom:3}}>
          <span style={{width:8,height:8,borderRadius:"50%",background:p.color,flexShrink:0}}/>
          <span style={{color:"#dee2e6"}}>{p.name}:</span>
          <span style={{color:"#fff",fontWeight:600,marginLeft:"auto"}}>{fmtK(p.value)}{suffix}</span>
        </div>
      ))}
    </div>
  );
};

function BalanceView() {
  const chartData = DATA.world_balance.map(d => ({...d, surplus: +(d.production - d.consumption).toFixed(0)}));
  return (
    <div>
      <h3 style={{margin:"0 0 4px",fontSize:16,fontWeight:700,color:"#f1f3f5"}}>Global Oil Supply vs Demand</h3>
      <p style={{margin:"0 0 16px",fontSize:12,color:"#868e96"}}>Thousand barrels per day · 1965–2024</p>
      <ResponsiveContainer width="100%" height={340}>
        <ComposedChart data={chartData} margin={{top:5,right:20,bottom:5,left:10}}>
          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)"/>
          <XAxis dataKey="year" tick={{fill:"#868e96",fontSize:11}} tickLine={false}/>
          <YAxis tick={{fill:"#868e96",fontSize:11}} tickLine={false} tickFormatter={fmt}/>
          <Tooltip content={<CustomTooltip suffix=" kbd"/>}/>
          <Legend wrapperStyle={{fontSize:12}}/>
          <Line type="monotone" dataKey="production" stroke="#2b8a3e" strokeWidth={2} dot={false} name="Production"/>
          <Line type="monotone" dataKey="consumption" stroke="#e8590c" strokeWidth={2} dot={false} name="Consumption"/>
          <Bar dataKey="surplus" name="Surplus/Deficit" fill="#364fc7" opacity={0.4}/>
        </ComposedChart>
      </ResponsiveContainer>
      <div style={{marginTop:20}}>
        <h3 style={{margin:"0 0 4px",fontSize:16,fontWeight:700,color:"#f1f3f5"}}>OPEC vs Non-OPEC Production</h3>
        <p style={{margin:"0 0 16px",fontSize:12,color:"#868e96"}}>Thousand barrels per day · 1990–2024</p>
        <ResponsiveContainer width="100%" height={300}>
          <AreaChart data={(() => {
            const byYear = {};
            DATA.opec_split.forEach(d => {
              if (!byYear[d.year]) byYear[d.year] = {year:d.year};
              byYear[d.year][d.entity] = d.value_kbd;
            });
            return Object.values(byYear).sort((a,b) => a.year - b.year);
          })()} margin={{top:5,right:20,bottom:5,left:10}}>
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)"/>
            <XAxis dataKey="year" tick={{fill:"#868e96",fontSize:11}} tickLine={false}/>
            <YAxis tick={{fill:"#868e96",fontSize:11}} tickLine={false} tickFormatter={fmt}/>
            <Tooltip content={<CustomTooltip suffix=" kbd"/>}/>
            <Legend wrapperStyle={{fontSize:12}}/>
            <Area type="monotone" dataKey="OPEC" stackId="1" stroke="#e8590c" fill="#e8590c" fillOpacity={0.6}/>
            <Area type="monotone" dataKey="Non-OPEC" stackId="1" stroke="#364fc7" fill="#364fc7" fillOpacity={0.6}/>
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

function PricesView() {
  const [showReal, setShowReal] = useState(true);
  const spotData = useMemo(() => {
    const byYear = {};
    DATA.spot_prices.forEach(d => {
      if (!byYear[d.year]) byYear[d.year] = {year:d.year};
      byYear[d.year][d.benchmark] = d.price_usd;
    });
    return Object.values(byYear).sort((a,b) => a.year - b.year);
  }, []);

  return (
    <div>
      <h3 style={{margin:"0 0 4px",fontSize:16,fontWeight:700,color:"#f1f3f5"}}>Oil Prices Since 1900</h3>
      <div style={{display:"flex",alignItems:"center",gap:12,margin:"0 0 16px"}}>
        <span style={{fontSize:12,color:"#868e96"}}>$/barrel</span>
        <button onClick={() => setShowReal(!showReal)} style={{background:showReal?"#364fc7":"#495057",border:"none",color:"#fff",padding:"4px 10px",borderRadius:4,fontSize:11,cursor:"pointer"}}>
          {showReal ? "Real (2024$)" : "Nominal"}
        </button>
      </div>
      <ResponsiveContainer width="100%" height={300}>
        <AreaChart data={DATA.historical_prices} margin={{top:5,right:20,bottom:5,left:10}}>
          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)"/>
          <XAxis dataKey="year" tick={{fill:"#868e96",fontSize:11}} tickLine={false}/>
          <YAxis tick={{fill:"#868e96",fontSize:11}} tickLine={false} tickFormatter={v=>"$"+v}/>
          <Tooltip content={<CustomTooltip suffix="/bbl"/>}/>
          {showReal ? <Area type="monotone" dataKey="real_2024_usd" stroke="#e8590c" fill="#e8590c" fillOpacity={0.3} name="Real (2024$)"/> :
            <Area type="monotone" dataKey="nominal_usd" stroke="#364fc7" fill="#364fc7" fillOpacity={0.3} name="Nominal"/>}
        </AreaChart>
      </ResponsiveContainer>
      <div style={{marginTop:24}}>
        <h3 style={{margin:"0 0 4px",fontSize:16,fontWeight:700,color:"#f1f3f5"}}>Spot Crude Benchmarks</h3>
        <p style={{margin:"0 0 16px",fontSize:12,color:"#868e96"}}>Annual average · $/barrel</p>
        <ResponsiveContainer width="100%" height={300}>
          <LineChart data={spotData} margin={{top:5,right:20,bottom:5,left:10}}>
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)"/>
            <XAxis dataKey="year" tick={{fill:"#868e96",fontSize:11}} tickLine={false}/>
            <YAxis tick={{fill:"#868e96",fontSize:11}} tickLine={false} tickFormatter={v=>"$"+v}/>
            <Tooltip content={<CustomTooltip suffix="/bbl"/>}/>
            <Legend wrapperStyle={{fontSize:12}}/>
            <Line type="monotone" dataKey="Brent" stroke="#e8590c" strokeWidth={2} dot={false}/>
            <Line type="monotone" dataKey="WTI" stroke="#364fc7" strokeWidth={2} dot={false}/>
            <Line type="monotone" dataKey="Dubai" stroke="#087f5b" strokeWidth={2} dot={false}/>
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

function EntitySelector({entities, selected, onChange, max=6}) {
  return (
    <div style={{display:"flex",flexWrap:"wrap",gap:4,marginBottom:12}}>
      {entities.map((e,i) => {
        const active = selected.includes(e);
        return (
          <button key={e} onClick={() => {
            if (active) onChange(selected.filter(s=>s!==e));
            else if (selected.length < max) onChange([...selected, e]);
          }} style={{
            background: active ? COLORS[i % COLORS.length]+"22" : "transparent",
            border: `1px solid ${active ? COLORS[i % COLORS.length] : "rgba(255,255,255,0.1)"}`,
            color: active ? COLORS[i % COLORS.length] : "#868e96",
            padding:"3px 8px",borderRadius:4,fontSize:10,cursor:"pointer",transition:"all 0.15s"
          }}>{e}</button>
        );
      })}
    </div>
  );
}

function ProductionView() {
  const [view, setView] = useState("country");
  const defaultCountries = ["US","Saudi Arabia","Russian Federation","China","Canada","Brazil"];
  const [selected, setSelected] = useState(defaultCountries);
  const allCountries = useMemo(() => [...new Set(DATA.production_countries.map(d=>d.entity))], []);

  const countryData = useMemo(() => {
    const byYear = {};
    DATA.production_countries.filter(d => selected.includes(d.entity)).forEach(d => {
      if (!byYear[d.year]) byYear[d.year] = {year:d.year};
      byYear[d.year][d.entity] = d.value_kbd;
    });
    return Object.values(byYear).sort((a,b) => a.year - b.year);
  }, [selected]);

  const regionData = useMemo(() => {
    const byYear = {};
    DATA.production_regional.filter(d => d.entity !== "Total World").forEach(d => {
      if (!byYear[d.year]) byYear[d.year] = {year:d.year};
      byYear[d.year][d.entity] = d.value_kbd;
    });
    return Object.values(byYear).sort((a,b) => a.year - b.year);
  }, []);

  const regions = [...new Set(DATA.production_regional.filter(d=>d.entity!=="Total World").map(d=>d.entity))];

  return (
    <div>
      <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:12}}>
        <h3 style={{margin:0,fontSize:16,fontWeight:700,color:"#f1f3f5"}}>Oil Production</h3>
        <div style={{display:"flex",gap:4}}>
          <button onClick={()=>setView("country")} style={{background:view==="country"?"#364fc7":"#495057",border:"none",color:"#fff",padding:"4px 10px",borderRadius:4,fontSize:11,cursor:"pointer"}}>By Country</button>
          <button onClick={()=>setView("region")} style={{background:view==="region"?"#364fc7":"#495057",border:"none",color:"#fff",padding:"4px 10px",borderRadius:4,fontSize:11,cursor:"pointer"}}>By Region</button>
        </div>
      </div>
      <p style={{margin:"0 0 8px",fontSize:12,color:"#868e96"}}>Thousand barrels per day · 1990–2024</p>
      {view === "country" && <EntitySelector entities={allCountries} selected={selected} onChange={setSelected}/>}
      <ResponsiveContainer width="100%" height={380}>
        {view === "country" ? (
          <LineChart data={countryData} margin={{top:5,right:20,bottom:5,left:10}}>
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)"/>
            <XAxis dataKey="year" tick={{fill:"#868e96",fontSize:11}} tickLine={false}/>
            <YAxis tick={{fill:"#868e96",fontSize:11}} tickLine={false} tickFormatter={fmt}/>
            <Tooltip content={<CustomTooltip suffix=" kbd"/>}/>
            <Legend wrapperStyle={{fontSize:11}}/>
            {selected.map((e,i) => <Line key={e} type="monotone" dataKey={e} stroke={COLORS[allCountries.indexOf(e) % COLORS.length]} strokeWidth={2} dot={false}/>)}
          </LineChart>
        ) : (
          <AreaChart data={regionData} margin={{top:5,right:20,bottom:5,left:10}}>
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)"/>
            <XAxis dataKey="year" tick={{fill:"#868e96",fontSize:11}} tickLine={false}/>
            <YAxis tick={{fill:"#868e96",fontSize:11}} tickLine={false} tickFormatter={fmt}/>
            <Tooltip content={<CustomTooltip suffix=" kbd"/>}/>
            <Legend wrapperStyle={{fontSize:11}}/>
            {regions.map(r => <Area key={r} type="monotone" dataKey={r} stackId="1" stroke={REGION_COLORS[r]} fill={REGION_COLORS[r]} fillOpacity={0.65}/>)}
          </AreaChart>
        )}
      </ResponsiveContainer>
    </div>
  );
}

function ConsumptionView() {
  const [view, setView] = useState("country");
  const defaultCountries = ["US","China","India","Saudi Arabia","Japan","Russian Federation"];
  const [selected, setSelected] = useState(defaultCountries);
  const allCountries = useMemo(() => [...new Set(DATA.consumption_countries.map(d=>d.entity))], []);

  const countryData = useMemo(() => {
    const byYear = {};
    DATA.consumption_countries.filter(d => selected.includes(d.entity)).forEach(d => {
      if (!byYear[d.year]) byYear[d.year] = {year:d.year};
      byYear[d.year][d.entity] = d.value_kbd;
    });
    return Object.values(byYear).sort((a,b) => a.year - b.year);
  }, [selected]);

  const regionData = useMemo(() => {
    const byYear = {};
    DATA.consumption_regional.filter(d => d.entity !== "Total World").forEach(d => {
      if (!byYear[d.year]) byYear[d.year] = {year:d.year};
      byYear[d.year][d.entity] = d.value_kbd;
    });
    return Object.values(byYear).sort((a,b) => a.year - b.year);
  }, []);

  const regions = [...new Set(DATA.consumption_regional.filter(d=>d.entity!=="Total World").map(d=>d.entity))];

  return (
    <div>
      <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:12}}>
        <h3 style={{margin:0,fontSize:16,fontWeight:700,color:"#f1f3f5"}}>Oil Consumption</h3>
        <div style={{display:"flex",gap:4}}>
          <button onClick={()=>setView("country")} style={{background:view==="country"?"#364fc7":"#495057",border:"none",color:"#fff",padding:"4px 10px",borderRadius:4,fontSize:11,cursor:"pointer"}}>By Country</button>
          <button onClick={()=>setView("region")} style={{background:view==="region"?"#364fc7":"#495057",border:"none",color:"#fff",padding:"4px 10px",borderRadius:4,fontSize:11,cursor:"pointer"}}>By Region</button>
        </div>
      </div>
      <p style={{margin:"0 0 8px",fontSize:12,color:"#868e96"}}>Thousand barrels per day · 1990–2024</p>
      {view === "country" && <EntitySelector entities={allCountries} selected={selected} onChange={setSelected}/>}
      <ResponsiveContainer width="100%" height={380}>
        {view === "country" ? (
          <LineChart data={countryData} margin={{top:5,right:20,bottom:5,left:10}}>
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)"/>
            <XAxis dataKey="year" tick={{fill:"#868e96",fontSize:11}} tickLine={false}/>
            <YAxis tick={{fill:"#868e96",fontSize:11}} tickLine={false} tickFormatter={fmt}/>
            <Tooltip content={<CustomTooltip suffix=" kbd"/>}/>
            <Legend wrapperStyle={{fontSize:11}}/>
            {selected.map((e,i) => <Line key={e} type="monotone" dataKey={e} stroke={COLORS[allCountries.indexOf(e) % COLORS.length]} strokeWidth={2} dot={false}/>)}
          </LineChart>
        ) : (
          <AreaChart data={regionData} margin={{top:5,right:20,bottom:5,left:10}}>
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)"/>
            <XAxis dataKey="year" tick={{fill:"#868e96",fontSize:11}} tickLine={false}/>
            <YAxis tick={{fill:"#868e96",fontSize:11}} tickLine={false} tickFormatter={fmt}/>
            <Tooltip content={<CustomTooltip suffix=" kbd"/>}/>
            <Legend wrapperStyle={{fontSize:11}}/>
            {regions.map(r => <Area key={r} type="monotone" dataKey={r} stackId="1" stroke={REGION_COLORS[r]} fill={REGION_COLORS[r]} fillOpacity={0.65}/>)}
          </AreaChart>
        )}
      </ResponsiveContainer>
    </div>
  );
}

function RefiningView() {
  const regionPie = DATA.refinery_regional_2024.map((d,i) => ({
    name: d.entity.replace("Total ",""),
    value: Math.round(d.value_kbd),
    color: COLORS[i]
  }));

  return (
    <div>
      <h3 style={{margin:"0 0 4px",fontSize:16,fontWeight:700,color:"#f1f3f5"}}>Global Refinery Capacity vs Throughput</h3>
      <p style={{margin:"0 0 16px",fontSize:12,color:"#868e96"}}>Thousand barrels per day · 1980–2024 · Utilisation = throughput ÷ capacity</p>
      <ResponsiveContainer width="100%" height={320}>
        <ComposedChart data={DATA.refinery_world.map(d => ({...d, utilisation: +((d.throughput/d.capacity)*100).toFixed(1)}))} margin={{top:5,right:60,bottom:5,left:10}}>
          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)"/>
          <XAxis dataKey="year" tick={{fill:"#868e96",fontSize:11}} tickLine={false}/>
          <YAxis yAxisId="left" tick={{fill:"#868e96",fontSize:11}} tickLine={false} tickFormatter={fmt}/>
          <YAxis yAxisId="right" orientation="right" tick={{fill:"#868e96",fontSize:11}} tickLine={false} tickFormatter={v=>v+"%"} domain={[60,100]}/>
          <Tooltip content={({active,payload,label}) => {
            if (!active || !payload?.length) return null;
            return <div style={{background:"rgba(15,15,20,0.95)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:6,padding:"10px 14px",fontSize:12}}>
              <div style={{color:"#868e96",marginBottom:6,fontWeight:600}}>{label}</div>
              {payload.map((p,i) => <div key={i} style={{display:"flex",gap:8,marginBottom:3}}>
                <span style={{width:8,height:8,borderRadius:"50%",background:p.color,flexShrink:0,marginTop:3}}/>
                <span style={{color:"#dee2e6"}}>{p.name}: <b style={{color:"#fff"}}>{p.name==="Utilisation" ? p.value+"%" : fmtK(p.value)+" kbd"}</b></span>
              </div>)}
            </div>;
          }}/>
          <Legend wrapperStyle={{fontSize:12}}/>
          <Area yAxisId="left" type="monotone" dataKey="capacity" stroke="#364fc7" fill="#364fc7" fillOpacity={0.15} name="Capacity"/>
          <Line yAxisId="left" type="monotone" dataKey="throughput" stroke="#e8590c" strokeWidth={2} dot={false} name="Throughput"/>
          <Line yAxisId="right" type="monotone" dataKey="utilisation" stroke="#2b8a3e" strokeWidth={2} dot={false} strokeDasharray="5 3" name="Utilisation"/>
        </ComposedChart>
      </ResponsiveContainer>
      <div style={{marginTop:24}}>
        <h3 style={{margin:"0 0 4px",fontSize:16,fontWeight:700,color:"#f1f3f5"}}>Regional Refining Capacity 2024</h3>
        <p style={{margin:"0 0 12px",fontSize:12,color:"#868e96"}}>Thousand barrels per day</p>
        <div style={{display:"flex",gap:20,alignItems:"center",flexWrap:"wrap"}}>
          <ResponsiveContainer width={260} height={260}>
            <PieChart>
              <Pie data={regionPie} cx="50%" cy="50%" innerRadius={55} outerRadius={100} dataKey="value" nameKey="name" label={({name,percent})=>name.split(" ")[0]+" "+Math.round(percent*100)+"%"} labelLine={false} style={{fontSize:10}}>
                {regionPie.map((d,i) => <Cell key={i} fill={d.color}/>)}
              </Pie>
              <Tooltip formatter={v=>fmtK(v)+" kbd"}/>
            </PieChart>
          </ResponsiveContainer>
          <div style={{display:"flex",flexDirection:"column",gap:6}}>
            {regionPie.map((d,i) => (
              <div key={i} style={{display:"flex",alignItems:"center",gap:8,fontSize:12}}>
                <span style={{width:10,height:10,borderRadius:2,background:d.color,flexShrink:0}}/>
                <span style={{color:"#dee2e6",minWidth:140}}>{d.name}</span>
                <span style={{color:"#fff",fontWeight:600}}>{fmtK(d.value)} kbd</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

function MarginsView() {
  const chartData = useMemo(() => {
    const byYear = {};
    DATA.refining_margins.forEach(d => {
      if (!byYear[d.year]) byYear[d.year] = {year:d.year};
      byYear[d.year][d.region] = d.margin_usd_bbl;
    });
    return Object.values(byYear).sort((a,b) => a.year - b.year);
  }, []);

  const regionKeys = [...new Set(DATA.refining_margins.map(d=>d.region))];
  const shortNames = {"USGC Medium Sour Coking":"USGC","NWE Light Sweet Cracking":"NWE","Singapore Medium Sour Hydrocracking":"Singapore"};

  return (
    <div>
      <h3 style={{margin:"0 0 4px",fontSize:16,fontWeight:700,color:"#f1f3f5"}}>Regional Refining Margins</h3>
      <p style={{margin:"0 0 16px",fontSize:12,color:"#868e96"}}>Nominal $/barrel · 2000–2024</p>
      <ResponsiveContainer width="100%" height={380}>
        <BarChart data={chartData} margin={{top:5,right:20,bottom:5,left:10}}>
          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.06)"/>
          <XAxis dataKey="year" tick={{fill:"#868e96",fontSize:11}} tickLine={false}/>
          <YAxis tick={{fill:"#868e96",fontSize:11}} tickLine={false} tickFormatter={v=>"$"+v}/>
          <Tooltip content={<CustomTooltip suffix="/bbl"/>}/>
          <Legend wrapperStyle={{fontSize:11}} formatter={v=>shortNames[v]||v}/>
          {regionKeys.map(r => <Bar key={r} dataKey={r} fill={MARGIN_COLORS[r]} name={r} opacity={0.85}/>)}
        </BarChart>
      </ResponsiveContainer>
      <div style={{marginTop:16,padding:12,background:"rgba(255,255,255,0.03)",borderRadius:8,border:"1px solid rgba(255,255,255,0.06)"}}>
        <div style={{fontSize:12,color:"#868e96",lineHeight:1.6}}>
          <b style={{color:"#dee2e6"}}>Reading margins:</b> These represent the theoretical gross margin from running a specific crude slate through a particular refinery configuration. Higher margins incentivise refiners to increase throughput. The 2022 spike reflects the post-COVID demand recovery combined with supply disruptions from the Russia–Ukraine conflict.
        </div>
      </div>
    </div>
  );
}

const VIEWS = {balance:BalanceView,prices:PricesView,production:ProductionView,consumption:ConsumptionView,refining:RefiningView,margins:MarginsView};

export default function Dashboard() {
  const [activeTab, setActiveTab] = useState("balance");
  const View = VIEWS[activeTab];

  const latestYear = 2024;
  const worldProd = DATA.world_balance.find(d=>d.year===latestYear);
  const brent = DATA.spot_prices.find(d=>d.benchmark==="Brent"&&d.year===latestYear);
  const refUtil = DATA.refinery_world.find(d=>d.year===latestYear);

  const stats = [
    {label:"World Production",value:worldProd?fmtK(Math.round(worldProd.production))+" kbd":"—"},
    {label:"World Consumption",value:worldProd?fmtK(Math.round(worldProd.consumption))+" kbd":"—"},
    {label:"Brent (2024 avg)",value:brent?"$"+brent.price_usd.toFixed(2)+"/bbl":"—"},
    {label:"Refinery Utilisation",value:refUtil?((refUtil.throughput/refUtil.capacity)*100).toFixed(1)+"%":"—"},
  ];

  return (
    <div style={{fontFamily:"'DM Sans',system-ui,sans-serif",background:"#0f0f14",color:"#f1f3f5",minHeight:"100vh",padding:"20px 16px"}}>
      <div style={{maxWidth:900,margin:"0 auto"}}>
        <div style={{marginBottom:24}}>
          <h1 style={{margin:0,fontSize:22,fontWeight:800,letterSpacing:"-0.5px",background:"linear-gradient(135deg,#e8590c,#d6336c)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>
            Oil Market Dashboard
          </h1>
          <p style={{margin:"4px 0 0",fontSize:12,color:"#5c5f66"}}>EI Statistical Review of World Energy · Updated 2024</p>
        </div>

        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(180px,1fr))",gap:10,marginBottom:20}}>
          {stats.map((s,i) => (
            <div key={i} style={{background:"rgba(255,255,255,0.03)",border:"1px solid rgba(255,255,255,0.06)",borderRadius:8,padding:"12px 14px"}}>
              <div style={{fontSize:11,color:"#5c5f66",textTransform:"uppercase",letterSpacing:"0.5px",marginBottom:4}}>{s.label}</div>
              <div style={{fontSize:18,fontWeight:700,color:"#f1f3f5"}}>{s.value}</div>
            </div>
          ))}
        </div>

        <div style={{display:"flex",gap:4,marginBottom:20,overflowX:"auto",paddingBottom:4}}>
          {tabs.map(t => (
            <button key={t.id} onClick={()=>setActiveTab(t.id)} style={{
              background: activeTab===t.id ? "#e8590c" : "rgba(255,255,255,0.04)",
              border: activeTab===t.id ? "1px solid #e8590c" : "1px solid rgba(255,255,255,0.08)",
              color: activeTab===t.id ? "#fff" : "#868e96",
              padding:"8px 16px",borderRadius:6,fontSize:12,fontWeight:600,cursor:"pointer",whiteSpace:"nowrap",transition:"all 0.15s"
            }}>{t.label}</button>
          ))}
        </div>

        <div style={{background:"rgba(255,255,255,0.02)",border:"1px solid rgba(255,255,255,0.06)",borderRadius:12,padding:"20px 16px"}}>
          <View/>
        </div>

        <div style={{marginTop:16,fontSize:10,color:"#5c5f66",textAlign:"center"}}>
          Source: Energy Institute Statistical Review of World Energy 2025 · Data loaded into SQLite for structured querying
        </div>
      </div>
    </div>
  );
}
